"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: summarize.py DATA_DIR OUT_FILE
"""
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

# --------------------------------------------------------------------------
# constants
# --------------------------------------------------------------------------

KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction("0.45359237"),
    "oz": Fraction("0.028349523125"),
}
UNIT_ALIASES = {"kgs": "kg", "kilogram": "kg", "kilograms": "kg", "gram": "g",
                "grams": "g", "gr": "g", "lbs": "lb", "pound": "lb",
                "pounds": "lb", "ounce": "oz", "ounces": "oz", "ozs": "oz"}
DEFAULT_UNIT = "kg"

DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor",
               "lakeside"]

# per-depot settings for delimited text
DELIMITED = {
    "east": dict(delim=",", quoted=True, cols=["id", "type", "shipped", "gross", "net", "status", "note"],
                 date="ymd", comma_decimal=False),
    "lakeside": dict(delim=",", quoted=True, cols=["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
                     date="ymd", comma_decimal=False),
    "river": dict(delim="\t", quoted=False, cols=["t", "ref", "shipped", "weight", "status"],
                  date="mdy", comma_decimal=False),
    "west": dict(delim=";", quoted=False, cols=["id", "typ", "shipped", "weight", "status", "note"],
                 date="dmy", comma_decimal=True),
    "harbor": dict(delim="|", quoted=False, cols=["rec", "ref", "date", "weight", "state"],
                   date="ymd", comma_decimal=False),
}
# columns that hold the id / type / date / status, in order of preference
ID_COLS = ["id", "ref"]
TYPE_COLS = ["type", "kind", "typ", "rec", "t"]
DATE_COLS = ["shipped", "date", "shipped_at"]
STATUS_COLS = ["status", "state"]

MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

SOUTH_LAYOUTS = {
    # name: (length, fields)  fields: name -> (start, end) 1-based inclusive
    "FW1": (42, dict(id=(1, 9), type=(10, 10), shipped=(11, 17), weight=(18, 25), status=(26, 26)),
            dict(date="yyyyddd", unit="g", scale=Fraction(1))),
    "FW2": (43, dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27)),
            dict(date="yyyymmdd", unit="kg", scale=Fraction(1, 100))),
    "FW3": (41, dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25)),
            dict(date="yyyyddd", unit="lb", scale=Fraction(1, 10))),
}
SOUTH_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}
HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}

ID_RE = re.compile(r"^\s*SH\W*0*(\d+)\s*$", re.I)


# --------------------------------------------------------------------------
# reading bytes / text
# --------------------------------------------------------------------------

def read_bytes(path):
    with open(path, "rb") as fh:
        data = fh.read()
    # gzip, whatever the name (possibly nested)
    while data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode_text(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", errors="replace")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le", errors="replace")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be", errors="replace")
    enc = None
    head = data[:2048]
    # BOM-less UTF-16 (looks like NUL interleaved ASCII)
    for cand, sl in (("utf-16-le", slice(1, 40, 2)), ("utf-16-be", slice(0, 40, 2))):
        if len(head) >= 4 and head[sl] and all(b == 0 for b in head[sl]):
            enc = cand
            break
    if enc is None:
        for line in head.split(b"\n")[:12]:
            m = re.match(rb"^#\s*charset\s*[:=]\s*([A-Za-z0-9_.:\-]+)", line)
            if m:
                enc = m.group(1).decode("ascii")
                break
    if enc is None:
        enc = "utf-8"
    try:
        return data.decode(enc, errors="replace")
    except LookupError:
        return data.decode("utf-8", errors="replace")


def norm_newlines(text):
    return text.replace("\r\n", "\n").replace("\r", "\n") if "\r" in text else text


# --------------------------------------------------------------------------
# value helpers
# --------------------------------------------------------------------------

def norm_unit(u):
    if u is None:
        return None
    u = u.strip().lower()
    u = UNIT_ALIASES.get(u, u)
    return u if u in KG else None


def parse_number(s, comma_decimal):
    s = s.strip().replace("\u00a0", " ").replace("\u202f", " ")
    s = re.sub(r"\s+", "", s)
    if comma_decimal:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def parse_weight_text(s, comma_decimal):
    """Return (Fraction value, unit-or-None) for text like '12.50 kg'."""
    m = re.match(r"^\s*([+-]?[0-9][0-9.,\s\u00a0\u202f]*?)\s*([A-Za-z]+)?\s*$", s)
    if not m:
        raise ValueError("bad weight %r" % s)
    return parse_number(m.group(1), comma_decimal), norm_unit(m.group(2))


def norm_status(s):
    if s is None:
        return ""
    return re.sub(r"[\s\-]+", "_", s.strip().lower())


def is_counted(status):
    return status in ("delivered", "delivered_late")


def norm_type(s):
    t = (s or "").strip().lower()
    if t.startswith("v"):
        return "void"
    if t.startswith("c") or t.startswith("a"):
        return "correction"
    return "new"


def norm_form(f):
    if f is None:
        return None
    f = f.strip()
    u = re.sub(r"\s+", "", f.upper())
    if u in ("ISO", "YMD", "YYYY-MM-DD", "YYYY/MM/DD"):
        return "ymd"
    if u in ("DMY", "DD-MM-YYYY", "DD/MM/YYYY", "DD.MM.YYYY"):
        return "dmy"
    if u in ("MDY", "MM/DD/YYYY", "MM-DD-YYYY", "MM.DD.YYYY"):
        return "mdy"
    if u == "SERIAL":
        return "serial"
    if u == "YYYYMMDD":
        return "yyyymmdd"
    if u == "YYYYDDD":
        return "yyyyddd"
    if re.match(r"^D{1,2}MMMYYYY$", u):
        return "dmony"
    return None


def date_from_shape(s):
    s = s.strip()
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?,?\s+(\d{4})$", s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    m = re.match(r"^(\d{4})\D(\d{1,2})\D(\d{1,2})$", s)
    if m:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    if re.match(r"^\d{8}$", s):
        return date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if re.match(r"^\d{7}$", s):
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
    raise ValueError("bad date %r" % s)


def parse_date(s, form):
    s = s.strip()
    try:
        if form == "ymd":
            m = re.match(r"^(\d{4})\D+(\d{1,2})\D+(\d{1,2})$", s)
            return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        if form in ("dmy", "mdy"):
            m = re.match(r"^(\d{1,2})\D+(\d{1,2})\D+(\d{4})$", s)
            a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            return date(y, b, a) if form == "dmy" else date(y, a, b)
        if form == "serial":
            return date(1899, 12, 30) + timedelta(days=int(Decimal(s)))
        if form == "yyyymmdd":
            return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        if form == "yyyyddd":
            return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
        if form == "dmony":
            return date_from_shape(s)
    except (AttributeError, ValueError, TypeError, ArithmeticError):
        pass
    return date_from_shape(s)


def utc_date_of(value, form):
    """Calendar date in UTC of a ship time/date given as text."""
    s = value.strip()
    if re.search(r"\d[T ]\d{1,2}:\d{2}", s):
        s2 = s.replace(" ", "T", 1) if "T" not in s else s
        dt = datetime.fromisoformat(s2.replace("z", "Z"))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.date()
    return parse_date(s, form)


def month_key(d):
    return "%04d-%02d" % (d.year, d.month)


def parse_id(s):
    if s is None:
        return None
    m = ID_RE.match(str(s))
    return int(m.group(1)) if m else None


# --------------------------------------------------------------------------
# record construction
# --------------------------------------------------------------------------

class Rec:
    __slots__ = ("num", "type", "status", "weight", "unit", "shipped", "form", "comma")

    def __init__(self, num, type_, status, weight, unit, shipped, form, comma):
        self.num = num
        self.type = type_
        self.status = status      # normalised
        self.weight = weight      # raw text or Fraction (already in `unit`)
        self.unit = unit
        self.shipped = shipped    # raw text
        self.form = form
        self.comma = comma

    def weight_kg(self):
        w = self.weight
        unit = self.unit or DEFAULT_UNIT
        if isinstance(w, str):
            val, own = parse_weight_text(w, self.comma)
            if own:
                unit = own
            w = val
        return w * KG[unit]

    def ship_date(self):
        return utc_date_of(self.shipped, self.form)


# --------------------------------------------------------------------------
# format readers.  Each returns (seq, [Rec ...]) in file order.
# --------------------------------------------------------------------------

def scan_delimited(text, delim, quoted):
    """Yield ('comment', line) or ('row', [fields])."""
    n = len(text)
    i = 0
    while i < n:
        # start of a record/line
        if text[i] == "\n":
            i += 1
            continue
        if text[i] == "#":
            j = text.find("\n", i)
            if j < 0:
                j = n
            yield "comment", text[i:j]
            i = j + 1
            continue
        if not quoted:
            j = text.find("\n", i)
            if j < 0:
                j = n
            line = text[i:j]
            i = j + 1
            if line.strip() == "":
                continue
            yield "row", line.split(delim)
            continue
        fields = []
        cur = []
        inq = False
        was_quoted = False
        while i < n:
            ch = text[i]
            if inq:
                if ch == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        cur.append('"')
                        i += 2
                        continue
                    inq = False
                    i += 1
                    continue
                cur.append(ch)
                i += 1
                continue
            if ch == '"' and not cur:
                inq = True
                was_quoted = True
                i += 1
                continue
            if ch == delim:
                fields.append("".join(cur))
                cur = []
                was_quoted = False
                i += 1
                continue
            if ch == "\n":
                i += 1
                break
            cur.append(ch)
            i += 1
        fields.append("".join(cur))
        if len(fields) == 1 and fields[0].strip() == "" and not was_quoted:
            continue
        yield "row", fields


def first_col(index, names):
    for n in names:
        if n in index:
            return index[n]
    return None


def read_delimited(depot, text):
    cfg = DELIMITED[depot]
    colset = set(cfg["cols"])
    header = list(cfg["cols"])
    seq = None
    date_form = cfg["date"]
    unit_dir = None
    comma = cfg["comma_decimal"]
    recs = []
    text = norm_newlines(text)
    for kind, payload in scan_delimited(text, cfg["delim"], cfg["quoted"]):
        if kind == "comment":
            line = payload
            m = re.match(r"^#\s*([A-Za-z][A-Za-z _\-]*?)\s*:\s*(.*?)\s*$", line)
            if m:
                name = re.sub(r"[\s_\-]+", " ", m.group(1).lower())
                val = m.group(2)
                if name == "seq":
                    mm = re.match(r"\d+", val)
                    if mm and seq is None:
                        seq = int(mm.group(0))
                elif name in ("dates", "date", "date format", "dateformat"):
                    f = norm_form(val)
                    if f:
                        date_form = f
                elif name in ("unit", "weight unit", "weight units", "weightunit"):
                    u = norm_unit(val.split()[0]) if val.split() else None
                    if u:
                        unit_dir = u
                    low = val.lower()
                    if "decimal comma" in low:
                        comma = True
                    elif "decimal point" in low or "decimal dot" in low:
                        comma = False
            else:
                mm = re.search(r"\bseq\s*=\s*(\d+)", line)
                if mm and seq is None:
                    seq = int(mm.group(1))
            continue
        row = payload
        fields = [f.strip() for f in row]
        low = [f.lower() for f in fields]
        if fields and all(f in colset for f in low):
            header = low
            continue
        index = {name: k for k, name in enumerate(header)}
        id_i = first_col(index, ID_COLS)
        if id_i is None or id_i >= len(fields):
            continue
        num = parse_id(fields[id_i])
        if num is None:
            continue  # trailer / total rows
        # weight column
        w_i = None
        for name, k in index.items():
            if name.startswith("gross") or name == "weight":
                w_i = k
                break
        row_unit = None
        if len(fields) == len(header) + 1 and w_i is not None:
            cand = fields[w_i + 1] if w_i + 1 < len(fields) else None
            if norm_unit(cand):
                row_unit = norm_unit(cand)
                del fields[w_i + 1]
            elif norm_unit(fields[-1]):
                row_unit = norm_unit(fields[-1])
                fields.pop()

        def get(i, fields=fields):
            return fields[i] if i is not None and i < len(fields) else ""

        t_i = first_col(index, TYPE_COLS)
        d_i = first_col(index, DATE_COLS)
        s_i = first_col(index, STATUS_COLS)
        typ = norm_type(get(t_i))
        raw_status = get(s_i)
        if depot == "harbor":
            status = HARBOR_STATUS.get(raw_status.upper(), norm_status(raw_status))
        else:
            status = norm_status(raw_status)
        # unit: named by field > row > directive > base
        unit = None
        if w_i is not None:
            m = re.search(r"_(kg|g|lb|oz)$", header[w_i])
            if m:
                unit = m.group(1)
        # for "<number> <unit>" text the suffix is applied in weight_kg (highest priority)
        if unit is None:
            unit = row_unit or unit_dir or DEFAULT_UNIT
        recs.append(Rec(num, typ, status, get(w_i), unit, get(d_i), date_form, comma))
    return seq, recs


def read_north(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            val = json.loads(line, parse_float=Decimal)
        except ValueError:
            continue
        objs = val if isinstance(val, list) else [val]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and o["meta"].get("seq") is not None:
                    try:
                        seq = int(o["meta"]["seq"])
                    except (TypeError, ValueError):
                        pass
                continue
            num = parse_id(o.get("id"))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            status = norm_status(o.get("status"))
            weight, unit = None, None
            for k, v in o.items():
                if k.lower().startswith("weight"):
                    m = re.search(r"_(kg|g|lb|oz)$", k.lower())
                    unit = m.group(1) if m else norm_unit(str(o.get("unit", ""))) or DEFAULT_UNIT
                    weight = Fraction(v) if isinstance(v, (Decimal, int)) else str(v)
                    break
            recs.append(Rec(num, typ, status, weight, unit, str(o.get("shipped_at") or ""), "ymd", False))
    return seq, recs


def read_south(text):
    seq = None
    recs = []
    layout = None
    by_len = {v[0]: k for k, v in SOUTH_LAYOUTS.items()}
    for line in text.split("\n"):
        if line.startswith("\x0c"):
            rest = line[1:]
            if rest.strip() == "" or "SHIPMENT LISTING" in rest:
                continue
            line = rest
        if not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if "SHIPMENT LISTING" in line:
            continue
        line = line.rstrip("\r")
        name = by_len.get(len(line))
        if name is None:
            name = layout if layout in SOUTH_LAYOUTS else None
            if name is None:
                continue
            line = line.ljust(SOUTH_LAYOUTS[name][0])
        length, fields, meta = SOUTH_LAYOUTS[name]

        def f(k, line=line, fields=fields):
            a, b = fields[k]
            return line[a - 1:b]

        num = parse_id(f("id"))
        if num is None:
            continue
        typ = norm_type(f("type"))
        status = SOUTH_STATUS.get(f("status").strip().upper(), norm_status(f("status")))
        try:
            weight = Fraction(int(f("weight").strip() or "0")) * meta["scale"]
        except ValueError:
            weight = None
        shipped = f("shipped").strip()
        recs.append(Rec(num, typ, status, weight, meta["unit"], shipped, meta["date"], False))
    return seq, recs


def local(tag):
    return tag.rsplit("}", 1)[-1] if isinstance(tag, str) else tag


def read_central(data):
    root = ET.fromstring(data)
    seq = None
    for k, v in root.attrib.items():
        if local(k).lower() == "seq":
            try:
                seq = int(v)
            except ValueError:
                pass
    root_unit = None
    for k, v in root.attrib.items():
        if local(k).lower() in ("weight-unit", "weight_unit", "weightunit", "unit"):
            root_unit = norm_unit(v)
    recs = []
    for el in root.iter():
        if local(el.tag) != "shipment":
            continue

        def get(name, el=el):
            for k, v in el.attrib.items():
                if local(k).lower() == name:
                    return v
            for ch in el:
                if local(ch.tag).lower() == name:
                    return ch.text or ""
            return None

        num = parse_id(get("id"))
        if num is None:
            continue
        typ = norm_type(get("type"))
        status = norm_status(get("status"))
        weight, unit = None, None
        wel = None
        for ch in el:
            if local(ch.tag).lower() == "weight":
                wel = ch
                break
        if wel is not None:
            weight = (wel.text or "").strip()
            for k, v in wel.attrib.items():
                if local(k).lower() == "unit":
                    unit = norm_unit(v)
        else:
            w = el.attrib.get("weight")
            if w is not None:
                weight = w
        if unit is None:
            unit = norm_unit(el.attrib.get("weight-unit") or el.attrib.get("unit") or "") or root_unit or DEFAULT_UNIT
        shipped = get("shipped") or get("shipped_at") or ""
        recs.append(Rec(num, typ, status, weight, unit, shipped.strip(), "dmony", False))
    return seq, recs


