def sniff_family(depot, text):
    if depot == "central":
        return "xml"
    if depot == "north":
        return "json"
    if depot == "south":
        return "fixed"
    if depot in DELIMITED:
        return "delimited"
    s = text.lstrip()[:1]
    if s == "<":
        return "xml"
    if s in "{[":
        return "json"
    return None


def read_export(path, depot):
    data = read_bytes(path)
    if depot == "central":
        return read_central(data)
    text = norm_newlines(decode_text(data))
    fam = sniff_family(depot, text)
    if fam == "json":
        return read_north(text)
    if fam == "fixed":
        return read_south(text)
    if fam == "delimited":
        return read_delimited(depot, text)
    if fam == "xml":
        return read_central(data)
    return None, []


def round2(x):
    d = Decimal(x.numerator) / Decimal(x.denominator) if False else None
    q = (Decimal(x.numerator) * 10 ** 6 // 1)  # placeholder (not used)
    return q


def fraction_round2(x):
    # exact round-half-up of a non-negative Fraction to 2 decimals
    scaled = x * 100
    n, d = scaled.numerator, scaled.denominator
    q, r = divmod(n, d)
    if 2 * r >= d:
        q += 1
    return Decimal(q) / Decimal(100)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        exports.setdefault(depot, []).append((name, path))

    corrections = 0
    resends = 0
    current = {}  # depot -> {num: Rec}
    for depot, files in exports.items():
        parsed = []
        for name, path in files:
            seq, recs = read_export(path, depot)
            parsed.append((seq if seq is not None else float("inf"), name, recs))
        parsed.sort(key=lambda p: (p[0], p[1]))
        cur = {}
        for _, _, recs in parsed:
            for r in recs:
                if r.type == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:  # void
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    def rank(d):
        return DEPOT_ORDER.index(d) if d in DEPOT_ORDER else len(DEPOT_ORDER)

    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots_out = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for num, ds in owners.items():
        depot = ds[0]
        r = current[depot][num]
        if not is_counted(r.status):
            continue
        w = r.weight_kg()
        m = month_key(r.ship_date())
        depots_out[depot][0] += 1
        depots_out[depot][1] += w
        ent = months.setdefault(m, [0, Fraction(0)])
        ent[0] += 1
        ent[1] += w

    out = {
        "depots": {d: {"shipments": v[0], "total_kg": float(fraction_round2(v[1]))}
                   for d, v in depots_out.items()},
        "months": {m: {"shipments": months[m][0], "total_kg": float(fraction_round2(months[m][1]))}
                   for m in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    os.makedirs(os.path.dirname(os.path.abspath(out_file)), exist_ok=True)
    with open(out_file, "w", encoding="utf-8") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")
    return 0


